pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes calldata fakeArgs) public {
        // Simulate a clone scenario: compute what owner() should be from P logic
        // P: shr(0x60, calldataload(add(offset, 0x0))) -> bottom 20 bytes of first slot
        // M: address(uint160(_getArgUint256(0x0))) -> bottom 20 bytes of full 32-byte slot cast to uint160
        // We embed fake immutable args into calldata and call c with mangled calldata?
        // Actually, c._getImmutableArgsOffset() reads calldata, so we craft calldata that mimics cloned args.
        // We'll just directly call the public owner() which relies on internal pure functions reading calldata.
        // To fuzz different immutable arg patterns, we need to call c with calldata that contains them.
        // The owner() function reads from calldata via _getImmutableArgsOffset(), which depends on calldatasize and last 2 bytes.
        // We cannot change c's calldata for a direct call to owner() without low-level tricks.
        // Instead, we can call owner() normally and check that it matches the P extraction method.
        // But C is not a clone; its immutable args are set at deploy time via clone factory, which we don't have.
        // We must deploy C directly, so its immutable args offset logic will read whatever calldata is passed to the call.
        // We can call owner() with crafted calldata that includes fake immutable args at the end.
        // However, owner() takes no arguments; its calldata is just the selector.
        // To vary the immutable args, we need to call c with different calldata lengths and content via low-level call.
        // We'll use a low-level call to invoke owner() with extra calldata appended after the selector, which the internal functions will interpret as immutable args.
        // The calldata structure: selector (4 bytes) + fake data + 2-byte length prefix for the immutable args section.
        // _getImmutableArgsOffset: offset = calldatasize - (shr(240, calldataload(calldatasize - 2)) + 2)
        // So the last 2 bytes of calldata must encode the length of the immutable args (excluding the 2-byte prefix itself).
        // We'll construct calldata: selector || random bytes (which we'll fuzz) || 2-byte length.
        // The length stored is the number of bytes of immutable args, not counting the length prefix.
        // We'll set the length to 32 (0x0020) to have one full 32-byte slot as the first arg.
        // The first 20 bytes of that slot will be the expected owner address.
        // The mutant reads the full 32 bytes as uint256 and casts to address, so if the upper 12 bytes are non-zero, it differs.
        // We'll fuzz the upper 12 bytes of that slot.

        // Build calldata: 4 bytes selector of owner() = 0x8da5cb5b
        // Followed by 32 bytes of data that represent the first immutable arg slot.
        // Then the last 2 bytes must be 0x0020 (big-endian length 32).
        bytes memory data = new bytes(4 + 32 + 2);
        // selector
        data[0] = 0x8d;
        data[1] = 0xa5;
        data[2] = 0xcb;
        data[3] = 0x5b;
        // copy fuzzed bytes into positions 4..35 (32 bytes)
        // fakeArgs is the fuzzed first slot
        // Ensure length matches
        require(fakeArgs.length == 32, "need 32 byte fuzz input");
        for (uint i = 0; i < 32; i++) {
            data[4 + i] = fakeArgs[i];
        }
        // last 2 bytes: 0x00 0x20 (big-endian 32)
        data[4 + 32] = 0x00;
        data[4 + 32 + 1] = 0x20;

        // Expected owner from P: first 20 bytes of the slot
        address expectedOwner;
        assembly {
            // fakeArgs is bytes in memory, first 20 bytes at add(fakeArgs, 32)
            expectedOwner := shr(0x60, mload(add(fakeArgs, 32)))
        }

        // Make low-level call to c with this calldata
        (bool ok, bytes memory ret) = address(c).call(data);
        require(ok, "call failed");
        // Decode returned address
        address actualOwner = abi.decode(ret, (address));

        // Assert: actualOwner must equal expectedOwner for all admissible inputs
        // The buggy version will return address(uint160(uint256(slot))), which differs when upper 12 bytes != 0
        assertTrue(actualOwner == expectedOwner);
    }
}

