pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address owner, address collateralToken, address debtToken, address factoryAddr) public {
        // Assemble immutable arg data mimicking the clone constructor layout:
        // [owner (0x0, 20 bytes), collateral (0x14, 20 bytes), debt (0x28, 20 bytes), factory (0x3c, 20 bytes)]
        // We use calldata injection directly via a low-level call to the fallback of the clone that reads immutable args.
        // Instead of full clone setup, we encode the immutable args as calldata to a raw call to c.
        // The test focuses solely on the debt() getter.
        // The fuzzer provides the four addresses; we require debt and collateral to be different to trigger the bug.
        vm.assume(debtToken != collateralToken);

        // Encode the immutable arguments as they would appear at the end of calldata during clone construction.
        // The clone extracts these using _getImmutableArgsOffset, which reads from the last 2 bytes.
        // We need to craft calldata that makes debt() via c (which is a Clone) return the correct token.
        // Since c is deployed as a standalone contract in setUp, its _getImmutableArgsOffset reads from its own calldata,
        // which is whatever we provide in the low-level call.

        // Prepare calldata: selector for debt() + appended immutable args.
        // debt() selector: first 4 bytes.
        bytes4 selector = C.debt.selector;
        // Layout of immutable args after the calldata (size encoded in last 2 bytes).
        // _getImmutableArgsOffset does:
        //   offset = calldatasize() - (shr(240, calldataload(calldatasize()-2)) + 2)
        // We encode args: owner(20) | collateral(20) | debt(20) | factory(20) = 80 bytes = 0x50.
        uint256 extraLength = 80; // 0x50
        // Build calldata: selector + 80 zero bytes (we'll overwrite with actual addresses) + 2-byte length.
        bytes memory calldataBytes = new bytes(4 + 80 + 2);
        // selector
        assembly {
            mstore(add(calldataBytes, 32), selector)
        }
        // immutable data
        assembly {
            mstore(add(calldataBytes, 36), owner)
            mstore(add(calldataBytes, 56), collateralToken)
            mstore(add(calldataBytes, 76), debtToken)
            mstore(add(calldataBytes, 96), factoryAddr)
        }
        // extra length in last 2 bytes (big-endian uint16)
        uint16 len16 = uint16(extraLength);
        assembly {
            let lastWordIdx := add(calldataBytes, add(32, 84)) // pointer to last 2 bytes in the bytes dynamic array
            mstore8(add(lastWordIdx, 0), byte(1, len16))
            mstore8(add(lastWordIdx, 1), byte(0, len16))
        }

        // Call c with this custom calldata.
        (bool ok, bytes memory ret) = address(c).call(calldataBytes);
        require(ok, "call failed");
        address returnedDebt = abi.decode(ret, (address));

        // The correct debt token is the one passed as debtToken.
        // The mutant will incorrectly return collateralToken.
        assertTrue(returnedDebt == debtToken);
    }
}

