pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, address to_, uint256 loanID_) public {
        vm.assume(caller != address(0));
        vm.assume(to_ != address(0));
        // Ensure caller is not the lender (lender is initially address(0) for any loan)
        vm.assume(caller != address(0));

        // Set up a loan with lender being address(0) (default)
        // We need a valid loan to exist, but approveTransfer checks msg.sender against lender
        // The key invariant: If caller is NOT the lender, approveTransfer should succeed in the correct contract.
        // In the buggy contract, it reverts.

        // Create a request and clear it to have at least a loan with lender = msg.sender
        // We'll make caller the lender for another loan, but we test with a loan where caller != lender.
        // To keep setup minimal, we rely on the fact that loans[loanID_] defaults to lender = address(0).
        // Since caller != address(0) and caller != address(0) (lender default), caller != lender holds.
        // The correct contract should allow it; buggy reverts.

        bool ok;
        vm.prank(caller);
        try c.approveTransfer(to_, loanID_) {
            ok = true;
        } catch {
            ok = false;
        }

        // After call, the approval mapping for loanID_ must be set to to_ in the correct version.
        // In the buggy version, the call reverts and mapping remains address(0).
        // The general rule: For any caller, loanID_ such that caller != loans[loanID_].lender,
        // approveTransfer does not revert AND sets approvals[loanID_] = to_.
        // The bug breaks this by reverting for caller != lender (since it checks == instead of !=).
        assertTrue(ok && c.approvals(loanID_) == to_);
    }
}
